        HttpServer s = HttpServer.create(new InetSocketAddress(Integer.parseInt(a[0])), 0);
        s.setExecutor(Executors.newCachedThreadPool());
        s.createContext("/__set", ex -> {
            String q = ex.getRequestURI().getQuery();
            String zip = q.split("=")[1];
            String body = new String(ex.getRequestBody().readAllBytes(), StandardCharsets.UTF_8);
            if (zip.equals("default")) def = body; else modes.put(zip, body);
            send(ex, 200, "ok");
        });
        s.createContext("/", ex -> {
            String q = ex.getRequestURI().getQuery();
            System.out.println("REQ " + ex.getRequestURI());
            System.out.flush();
            Map<String,String> p = new HashMap<>();
            if (q != null) for (String kv : q.split("&")) { String[] x = kv.split("=",2); p.put(x[0], x.length>1?x[1]:""); }
            String key = p.getOrDefault("zip","") + ":" + p.getOrDefault("service","");
            String m = modes.getOrDefault(key, modes.getOrDefault(p.getOrDefault("zip",""), def));
            // mode: status|body  or sleep:ms|status|body
            if (m.startsWith("sleep:")) {
                int i = m.indexOf('|');
                long ms = Long.parseLong(m.substring(6, i));
                try { Thread.sleep(ms); } catch (Exception e) {}
                m = m.substring(i+1);
            }
            int i = m.indexOf('|');
            send(ex, Integer.parseInt(m.substring(0,i)), m.substring(i+1));
        });
        s.start();
        System.out.println("stub up " + a[0]);
    }
    static void send(HttpExchange ex, int code, String body) throws IOException {
        byte[] b = body.getBytes(StandardCharsets.UTF_8);
        ex.getResponseHeaders().add("Content-Type", "application/json");
        ex.sendResponseHeaders(code, b.length);
        ex.getResponseBody().write(b); ex.close();
    }
}
